def solve(n, roads):
    import heapq

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Kruskal's algorithm
    def kruskals():
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x == root_y:
                return False
            parent[root_y] = root_x
            return True

        # Sort all roads by weight
        edges = []
        for u, v, w in roads:
            edges.append((w, u, v))
        edges.sort()

        total_cost = 0
        count = 0
        for w, u, v in edges:
            if union(u, v):
                total_cost += w
                count += 1
                if count == n - 1:
                    return total_cost
        return -1

    # Prim's algorithm (alternative)
    def prims():
        visited = [False] * n
        min_heap = [(0, 0)]
        total_cost = 0
        edges_used = 0

        while min_heap:
            weight, u = heapq.heappop(min_heap)
            if visited[u]:
                continue
            visited[u] = True
            total_cost += weight
            edges_used += 1
            if edges_used == n:
                return total_cost

            for v, w in graph[u]:
                if not visited[v]:
                    heapq.heappush(min_heap, (w, v))
        return -1

    # Try both algorithms to handle edge cases
    return kruskals()
```

