def solve(grid, start, goal):
    if start == goal and grid[start[0]][start[1]] == '.':
        return [start]
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()
        if (x, y) == goal:
            path = [(x, y)]
            while (x, y)!= start:
                for dx, dy in directions:
                    nx, ny = x - dx, y - dy
                    if (nx, ny) in visited and (nx, ny)!= (x - dx, y - dy):
                        path.insert(0, (nx, ny))
                        x, y = nx, ny
                        break
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= nx < rows) and (0 <= ny < cols) and grid[nx][ny] == '.' and (nx, ny) not in visited:
                queue.append((nx, ny))
                visited.add((nx, ny))

    return []
