        r, c = pos
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def neighbors(pos):
        r, c = pos
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            yield (r + dr, c + dc)

    visited = set()
    stack = [(start, [start])]
    while stack:
        (pos, path) = stack.pop()
        if pos == goal:
            return path
        if pos not in visited:
            visited.add(pos)
            for n in neighbors(pos):
                if is_valid(n) and n not in visited:
                    stack.append((n, path + [n]))
    return []
