from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([start])
    visited = set([start])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    while queue:
        row, col = queue.popleft()
        if (row, col) == goal:
            path = []
            while (row, col)!= start:
                path.append((row, col))
                for dr, dc in directions:
                    r, c = row - dr, col - dc
                    if (r, c) in visited:
                        row, col = r, c
                        break
            path.append(start)
            path.reverse()
            return path

        for dr, dc in directions:
            r, c = row + dr, col + dc
            if is_valid(r, c) and (r, c) not in visited:
                queue.append((r, c))
                visited.add((r, c))

    return []
