from collections import deque

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up

    if start == goal and grid[start[0]][start[1]]!= '#':
        return [start]

    stack = deque([(start, [start], False)])
    visited = set(start)

    while stack:
        cell, path, found_goal = stack.pop()

        if path[-1] == goal:
            return path

        for dr, dc in directions:
            r, c = cell[0] + dr, cell[1] + dc
            if 0 <= r < rows and 0 <= c < cols and grid[r][c]!= '#' and (r, c) not in visited:
                visited.add((r, c))
                new_path = path + [(r, c), (r + dr, c + dc)]
                stack.append(((r, c), new_path, r == goal[0] and c == goal[1]))

        if found_goal:
            stack.appendleft((cell, path, found_goal))

    return []
