from collections import deque

DIRECTIONS = [(0, 1), (0, -1), (1, 0), (-1, 0)]

def solve(grid, start, goal):
    rows, cols = len(grid), len(grid[0])

    if isinstance(start, str):
        start = (ord(start[0]) - ord('A'), int(start[1])-1)
    if isinstance(goal, str):
        goal = (ord(goal[0]) - ord('A'), int(goal[1])-1)

    if start[0] < 0 or start[0] >= rows or start[1] < 0 or start[1] >= cols:
        return []
    if goal[0] < 0 or goal[0] >= rows or goal[1] < 0 or goal[1] >= cols:
        return []
    if grid[start[0]][start[1]] == '#':
        return []
    if start == goal:
        return [start]

    queue = deque([(start, [start])])
    visited = set([start])

    while queue:
        position, path = queue.popleft()
        for direction in DIRECTIONS:
            new_position = position[0] + direction[0], position[1] + direction[1]
            if (0 <= new_position[0] < rows and 0 <= new_position[1] < cols and
                grid[new_position[0]][new_position[1]] == '.' and new_position not in visited):
                if new_position == goal:
                    return path + [new_position]
                queue.append((new_position, path + [new_position]))
                visited.add(new_position)

    return []
